const list13 = [
  'afganistan', 'arab saudi', 'armenia', 'azerbaijan', 'bahrain',
  'bangladesh', 'bhutan', 'brunei', 'china', 'filipina',
  'georgia', 'hong kong', 'india'
];

for (const country of list13) {
  const cData = cleanDatabase[country];
  if (!cData) continue;
  const baseDir = path.join('json', 'firstname_lastname', 'asia', country);

  function cleanUnique100(arr) {
    const set = new Set();
    const res = [];
    for (let item of arr) {
      // Stripping any code suffix if remaining
      item = item.replace(/-(F|M|L|FL|ML|Female|Male|FHK|MHK|FHKS|BD|BH|CN|HK|AZ|IN|PH|GE|B|L|FL|FLL|BL|BHL|BN|BNL|ALT\d+|Alt\d+)/gi, '').replace(/Alt\d+/gi, '').trim();
      if (!set.has(item) && item.length > 0) {
        set.add(item);
        res.push(item);
      }
      if (res.length >= 100) break;
    }
    return res;
  }

  const mF = cleanUnique100(cData.mF);
  const mL = cleanUnique100(cData.mL);
  const fF = cleanUnique100(cData.fF);
  const fL = cleanUnique100(cData.fL);

  fs.writeFileSync(path.join(baseDir, 'male', 'firstname.json'), JSON.stringify(mF, null, 2));
  fs.writeFileSync(path.join(baseDir, 'male', 'lastname.json'), JSON.stringify(mL, null, 2));
  fs.writeFileSync(path.join(baseDir, 'female', 'firstname.json'), JSON.stringify(fF, null, 2));
  fs.writeFileSync(path.join(baseDir, 'female', 'lastname.json'), JSON.stringify(fL, null, 2));

  console.log(`${country}: mF=${mF.length}, mL=${mL.length}, fF=${fF.length}, fL=${fL.length}`);
}
